   255→// POST /api/v2/snippets/:id/like - 스니펫 좋아요
   256→func LikeSnippet(db *sql.DB) http.HandlerFunc {
   257→	return func(w http.ResponseWriter, r *http.Request) {
   258→		id := r.PathValue("id")
   259→
   260→		_, err := db.Exec("UPDATE snippets SET likes = likes + 1 WHERE id = ?", id)
   261→		if err != nil {
   262→			http.Error(w, err.Error(), http.StatusInternalServerError)
   263→			return
   264→		}
   265→
   266→		var likes int
   267→		db.QueryRow("SELECT likes FROM snippets WHERE id = ?", id).Scan(&likes)
   268→
   269→		w.Header().Set("Content-Type", "application/json")
   270→		json.NewEncoder(w).Encode(SnippetResponse{
   271→			Success: true,
   272→			Data: map[string]interface{}{
   273→				"likes": likes,
   274→			},
   275→		})
   276→	}
   277→}
