   279→// GET /api/v2/snippets/search - 스니펫 검색
   280→func SearchSnippets(db *sql.DB) http.HandlerFunc {
   281→	return func(w http.ResponseWriter, r *http.Request) {
   282→		q := r.URL.Query().Get("q")
   283→		if q == "" {
   284→			http.Error(w, "검색어를 입력하세요", http.StatusBadRequest)
   285→			return
   286→		}
   287→
   288→		query := `
   289→		SELECT id, title, code, author, tags, likes, created_at, updated_at
   290→		FROM snippets
   291→		WHERE title LIKE ? OR code LIKE ? OR author LIKE ?
   292→		ORDER BY created_at DESC
   293→		LIMIT 20
   294→		`
   295→
   296→		searchTerm := "%" + q + "%"
   297→		rows, err := db.Query(query, searchTerm, searchTerm, searchTerm)
   298→		if err != nil {
   299→			http.Error(w, err.Error(), http.StatusInternalServerError)
   300→			return
   301→		}
   302→		defer rows.Close()
   303→
   304→		var snippets []Snippet
   305→		for rows.Next() {
   306→			var s Snippet
   307→			var tags string
   308→			if err := rows.Scan(&s.ID, &s.Title, &s.Code, &s.Author, &tags, &s.Likes, &s.CreatedAt, &s.UpdatedAt); err != nil {
   309→				continue
   310→			}
   311→			if err := json.Unmarshal([]byte(tags), &s.Tags); err != nil {
   312→				s.Tags = []string{}
   313→			}
   314→			snippets = append(snippets, s)
   315→		}
   316→
   317→		w.Header().Set("Content-Type", "application/json")
   318→		json.NewEncoder(w).Encode(SnippetResponse{
   319→			Success: true,
   320→			Data:    snippets,
   321→		})
   322→	}
   323→}
