    16→  final String title;
    17→  final String code;
    18→  final String author;
    19→  final List<String> tags;
    20→  final int likes;
    21→  final String createdAt;
    22→
    23→  SnippetResponse({
    24→    required this.id,
    25→    required this.title,
    26→    required this.code,
    27→    required this.author,
    28→    required this.tags,
    29→    required this.likes,
