   108→class ApiException implements Exception {
   109→  final String message;
   110→  final int? statusCode;
   111→  final dynamic originalError;
   112→
   113→  ApiException({
   114→    required this.message,
   115→    this.statusCode,
   116→    this.originalError,
   117→  });
   118→
   119→  @override
   120→  String toString() =>
   121→      'ApiException: $message${statusCode != null ? ' (HTTP $statusCode)' : ''}';
   122→}
