   126→class HubApiClient {
   127→  static final HubApiClient _instance = HubApiClient._internal();
   128→
   129→  factory HubApiClient({String baseUrl = 'http://localhost:3000/api/v2'}) {
   130→    _instance._baseUrl = baseUrl;
   131→    return _instance;
   132→  }
   133→
   134→  HubApiClient._internal();
   135→
   136→  late String _baseUrl;
   137→  late Dio _dio;
   138→  bool _initialized = false;
   139→
   140→  Future<void> initialize() async {
   141→    if (_initialized) return;
   142→
   143→    _dio = Dio(
   144→      BaseOptions(
   145→        baseUrl: _baseUrl,
   146→        connectTimeout: const Duration(seconds: 10),
   147→        receiveTimeout: const Duration(seconds: 10),
   148→        sendTimeout: const Duration(seconds: 10),
   149→        contentType: 'application/json',
   150→      ),
   151→    );
   152→
   153→    // 요청 로깅 인터셉터
   154→    _dio.interceptors.add(
   155→      LoggingInterceptor(),
   156→    );
   157→
   158→    // 에러 처리 인터셉터
   159→    _dio.interceptors.add(
   160→      ErrorInterceptor(),
   161→    );
   162→
   163→    _initialized = true;
   164→  }
