   168→  /// 스니펫 목록 조회 (페이징 & 필터)
   169→  /// [page]: 1부터 시작
   170→  /// [limit]: 페이지당 아이템 수
   171→  /// [tag]: 필터링 태그 (선택사항)
   172→  Future<List<SnippetResponse>> getSnippets({
   173→    int page = 1,
   174→    int limit = 10,
   175→    String? tag,
   176→  }) async {
   177→    try {
   178→      final response = await _dio.get<Map<String, dynamic>>(
   179→        '/snippets',
   180→        queryParameters: {
   181→          'page': page,
   182→          'limit': limit,
   183→          if (tag != null) 'tag': tag,
   184→        },
   185→      );
   186→
   187→      final data = response.data?['data'] as List? ?? [];
   188→      return data
   189→          .map((item) => SnippetResponse.fromJson(item as Map<String, dynamic>))
   190→          .toList();
   191→    } on DioException catch (e) {
   192→      throw ApiException(
   193→        message: '스니펫 조회 실패',
   194→        statusCode: e.response?.statusCode,
   195→        originalError: e,
   196→      );
   197→    }
   198→  }
