   221→  /// 스니펫 단건 조회
   222→  Future<SnippetResponse> getSnippet(String id) async {
   223→    try {
   224→      final response = await _dio.get<Map<String, dynamic>>('/snippets/$id');
   225→      return SnippetResponse.fromJson(
   226→        response.data?['data'] as Map<String, dynamic>? ?? {},
   227→      );
   228→    } on DioException catch (e) {
   229→      throw ApiException(
   230→        message: '스니펫 조회 실패',
   231→        statusCode: e.response?.statusCode,
   232→        originalError: e,
   233→      );
