   237→  /// 스니펫 업로드
   238→  Future<SnippetResponse> createSnippet({
   239→    required String title,
   240→    required String code,
   241→    required List<String> tags,
   242→  }) async {
   243→    try {
   244→      final response = await _dio.post<Map<String, dynamic>>(
   245→        '/snippets',
   246→        data: {
   247→          'title': title,
   248→          'code': code,
   249→          'tags': tags,
   250→        },
   251→      );
   252→
   253→      return SnippetResponse.fromJson(
   254→        response.data?['data'] as Map<String, dynamic>? ?? {},
   255→      );
   256→    } on DioException catch (e) {
   257→      throw ApiException(
   258→        message: '스니펫 업로드 실패',
   259→        statusCode: e.response?.statusCode,
   260→        originalError: e,
   261→      );
   262→    }
