     5→
     6→class FileInfo {
     7→  final String name;
     8→  final String path;
     9→  final DateTime modified;
    10→  final int size;
    11→
    12→  FileInfo({
    13→    required this.name,
    14→    required this.path,
    15→    required this.modified,
    16→    required this.size,
    17→  });
    18→}
    19→
    20→class FileManager {
    21→  late Directory _codeDirectory;
    22→  static const String _codeFolder = 'freelang_code';
    23→
    24→  Future<void> initialize() async {
    25→    final documents = await getApplicationDocumentsDirectory();
    26→    _codeDirectory = Directory('${documents.path}/$_codeFolder');
    27→    if (!_codeDirectory.existsSync()) {
    28→      _codeDirectory.createSync(recursive: true);
    29→    }
    30→  }
    31→
    32→  /// 파일 목록 가져오기
    33→  Future<List<FileInfo>> listFiles() async {
    34→    final files = _codeDirectory.listSync();
    35→    return files
    36→        .whereType<File>()
    37→        .where((f) => f.path.endsWith('.fl'))
    38→        .map((f) {
    39→          final stat = f.statSync();
    40→          return FileInfo(
    41→            name: f.path.split('/').last,
    42→            path: f.path,
    43→            modified: stat.modified,
    44→            size: stat.size,
    45→          );
    46→        })
    47→        .toList()
    48→        ..sort((a, b) => b.modified.compareTo(a.modified));
    49→  }
    50→
    51→  /// 파일 읽기
    52→  Future<String> readFile(String path) async {
    53→    return File(path).readAsString();
    54→  }
    55→
    56→  /// 파일 저장
    57→  Future<void> saveFile(String name, String content) async {
    58→    if (!name.endsWith('.fl')) {
    59→      name += '.fl';
    60→    }
    61→    final file = File('${_codeDirectory.path}/$name');
    62→    await file.writeAsString(content);
    63→  }
    64→
    65→  /// 파일 삭제
    66→  Future<void> deleteFile(String path) async {
    67→    await File(path).delete();
    68→  }
    69→
    70→  /// 파일 이름 변경
    71→  Future<void> renameFile(String oldPath, String newName) async {
    72→    await File(oldPath).rename('${_codeDirectory.path}/$newName');
    73→  }
    74→
    75→  /// 디렉토리 경로
    76→  String get codePath => _codeDirectory.path;
    77→}
